def c3(v): return f"{v[0]}·{v[1]}·{v[2]}"
def kx(lo, hi, comps):
    g = [m for m in EXTRA_M if lo <= m[0] < hi and m[2] in comps]
    gl = [e for e in EXTRA_E if lo <= e[8] < hi and e[2] in comps]
    return f"{len(g)}경기 {len(gl)}골"
